package com.yeyamo_mobile.api.booking_service.infrastructure.web;import org.springframework.context.annotation.*;import io.swagger.v3.oas.models.*;import io.swagger.v3.oas.models.info.Info;import io.swagger.v3.oas.models.security.*;@Configuration public class OpenApiConfig{@Bean OpenAPI bookingOpenApi(){return new OpenAPI().info(new Info().title("YeYamo Booking API").version("v1").description("Activity booking, availability and payment saga")).components(new Components().addSecuritySchemes("bearerAuth",new SecurityScheme().type(SecurityScheme.Type.HTTP).scheme("bearer").bearerFormat("JWT"))).addSecurityItem(new SecurityRequirement().addList("bearerAuth"));}}
